import {useEffect, useState} from 'react';
import {Rating} from '../../../../model/interface/dashboard.interface';
import TableCM from '../../../components/Table';
import {Image, ScrollView, StyleSheet, Text, View} from 'react-native';
import {Font, FontSize, String} from '../../../../constants';
import TextCM from '../../../components/Text';

type Props = {
  taskRating: Rating[];
};
const DashboardTaskRating = ({taskRating}: Props) => {
  const [data, setData] = useState<any>([]);
  const tranformData = (taskRating: Rating[]) => {
    const newData = taskRating.map(item => {
      return {
        Asignee: (
          <View style={styles.container} key={item.userId}>
            <View style={styles.avatarContainer}>
              <Image
                width={32}
                height={32}
                borderRadius={25}
                source={{
                  uri: item.avatar || String.DEFAULT_IMAGE,
                }}
              />
            </View>
            <View style={styles.infoContainer}>
              <Text style={styles.username}>{item.name}</Text>
              <Text style={styles.email}>{item.email}</Text>
            </View>
          </View>
        ),
        'HM.board.5-star': item.ratingTaskCounts[5].count || 0,
        'HM.board.4-star': item.ratingTaskCounts[4].count || 0,
        'HM.board.3-star': item.ratingTaskCounts[3].count || 0,
        'HM.board.2-star': item.ratingTaskCounts[2].count || 0,
        'HM.board.1-star': item.ratingTaskCounts[1].count || 0,
      };
    });
    setData(newData);
  };
  useEffect(() => {
    tranformData(taskRating);
  }, [taskRating]);
  return (
    <>
      <TextCM
        style={{
          fontSize: 16,
          fontFamily: Font.InterMedium500,
          padding: 20,
          color: 'rgba(0, 32, 77, .95)',
        }}>
        {'Số lượng task được đánh giá theo assignee'}
      </TextCM>
      <ScrollView>
        <TableCM
          tableData={data}
          tableHeaders={[
            'Asignee',
            'HM.board.5-star',
            'HM.board.4-star',
            'HM.board.3-star',
            'HM.board.2-star',
            'HM.board.1-star',
          ]}
          styleTextHeader={{
            fontSize: FontSize.FontTiny,
            fontFamily: Font.InterMedium500,
            color: '#00204DB2',
          }}
          styleHeader={{backgroundColor: '#f1f1f1'}}
        />
      </ScrollView>
    </>
  );
};

export default DashboardTaskRating;

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#FFFFFF',
    padding: 10,
  },
  avatarContainer: {
    width: 32,
    height: 32,
    borderRadius: 25,
    backgroundColor: '#E0E0E0',
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 10,
  },
  infoContainer: {
    flexDirection: 'column',
  },
  username: {
    color: '#00204de5',
    fontFamily: Font.InterRegular400,
    fontSize: 14,
  },
  email: {
    color: '#00204d99',
    fontSize: 12,
    fontFamily: Font.InterRegular400,
    marginTop: 2,
  },
});
